from __future__ import annotations

from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .enums.kind1 import Kind1OrStr
from .segment_line import SegmentLine, SegmentLineDict
from .segment_translation_metadata import SegmentTranslationMetadata, SegmentTranslationMetadataDict
from .segment_words import SegmentWords, SegmentWordsDict


class Segment(SdkBaseModel):
    autogenerated: bool
    """Whether the segment is autogenerated."""

    cue_end: float
    """The cue end timestamp in milliseconds from the start of the video."""

    cue_start: float
    """The cue start timestamp in milliseconds from the start of the video."""

    enabled: bool
    """Whether the segment is enabled."""

    id: str
    """The segment identifier."""

    kind: Kind1OrStr
    """The type of caption that the segment originates from.

    Option descriptions:
     * ``captions`` - The segment originates from a captions file.
     * ``subtitles`` - The segment originates from a captions and subtitles file."""

    language: str
    """The language of the segment."""

    lines: list[SegmentLine]
    """The line data for the segment."""

    speaker: str | None
    """The speaker identifier."""

    text_track_uri: str
    """The relative URI of the text track that the segment comes from."""

    translation_metadata: Optional[SegmentTranslationMetadata] = UNSET
    """The translation metadata of the segment."""

    video_uri: Optional[str] = UNSET
    """The canonical relative URI of the segment's video."""

    words: list[SegmentWords]
    """The word data for the segment."""


class SegmentDict(TypedDict):
    autogenerated: bool
    cue_end: float
    cue_start: float
    enabled: bool
    id: str
    kind: Kind1OrStr
    language: str
    lines: list[SegmentLine | SegmentLineDict]
    speaker: str | None
    text_track_uri: str
    translation_metadata: NotRequired[SegmentTranslationMetadata | SegmentTranslationMetadataDict]
    video_uri: NotRequired[str]
    words: list[SegmentWords | SegmentWordsDict]
